<script setup lang="ts">
import {
  ref,
  computed,
  watch,
  watchEffect,
  markRaw,
  nextTick,
  onMounted,
  type Component,
} from 'vue';
import { defineAsyncComponent } from 'vue';
import { useQuasar } from 'quasar';
import { useRoute, useRouter } from 'vue-router';
import { useAuthStore } from '@stores/auth-store';
import { useMapMenuStore } from '@stores/map/map-menu-store';
import { useMapContentStore } from '@stores/map/map-content-store';
import { useUserSettingsStore } from '@stores/user-settings-store';
import { useLocalPropertiesStore } from '@stores/local-properties-store';
import { useSyncedPropertiesStore } from '@stores/synced-properties-store';
import { useMeta } from 'quasar';
import { i18n } from '@services/locale';
import WodoreLogo from 'components/wodore/WodoreLogo.vue';
import WdPlaceSearchMenu from 'components/search/WdPlaceSearchMenu.vue';
import WdPlaceSearchDialog from 'components/search/WdPlaceSearchDialog.vue';
import WdBottomSheet from '@components/utils/WdBottomSheet.vue';
import { useRequestProgress } from '@composables/useRequestProgress';
import { getEnv } from '@services/runtimeEnv';

// Initialize stores
const _authStore = useAuthStore();
const menuStore = useMapMenuStore();
const contentStore = useMapContentStore();

// Initialize stores (this will create localStorage keys on first load)
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const userSettingsStore = useUserSettingsStore();
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const localPropertiesStore = useLocalPropertiesStore();
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const syncedPropertiesStore = useSyncedPropertiesStore();

const $q = useQuasar();
const route = useRoute();
const router = useRouter();

const isMobile = computed(() => $q.screen.lt.md);

// Topbar utility cluster (feedback / language / theme): desktop-only, and
// only where it has room. Below 900px the cluster would collide with the
// side panel as soon as the panel slides it left (panel is ≥ 380px while
// the viewport is small), so it hides from the topbar below 900px — the
// buttons move into the menu-drawer toolbar, exactly like on mobile.
const showTopbarUtils = computed(() => $q.screen.width >= 900);
// Menu-drawer toolbar (logo + language/theme/feedback + CLOSE) renders on
// mobile AND across the whole band where the left-aligned pill sits under
// the open drawer (770-1099px — there the pill's own menu toggle is
// covered, and a docked ≥ 610px Quasar drawer has no backdrop/ESC, so the
// toolbar close is the only exit). Deliberately wider than the utils
// gate: between 900 and 1099 both surfaces show, which is fine — they
// never overlap each other.
const showDrawerToolbar = computed(() => $q.screen.width < 1100);

// API request progress (bottom edge of the floating topbar pill, replaces
// the viewport-top QAjaxBar)
const { visible: progressVisible } = useRequestProgress();

// Menu drawer state
const menuDrawerOpen = computed({
  get: () => menuStore.menuOpen,
  set: val => {
    if (val) {
      menuStore.openMenu();
    } else {
      menuStore.closeMenu();
    }
  },
});

const showDialog = ref(false);

// Track whether we should navigate when dialog closes
let shouldNavigateOnHide = false;

// check if route.meta.dialog is set
watchEffect(() => {
  const newDialogState = route.meta?.dialog as boolean;
  showDialog.value = newDialogState;
});

// Set up router guards to track navigation source
router.beforeEach((to, from, next) => {
  const fromDialog = from.meta?.dialog as boolean;
  const toDialog = to.meta?.dialog as boolean;

  if (fromDialog && !toDialog) {
    shouldNavigateOnHide = false;
  }

  next();
});

// Handle dialog close via backdrop click, ESC key, or close button
function onDialogHide() {
  if (!shouldNavigateOnHide) {
    return;
  }

  shouldNavigateOnHide = false;

  if (window.history.state.back) {
    router.back();
  } else {
    router.push({ name: 'map' });
  }
}

// Watch for dialog state changes
watchEffect(() => {
  if (showDialog.value) {
    nextTick(() => {
      shouldNavigateOnHide = true;
    });
  }
});

// Content drawer state (synced with store)
const contentDrawerOpen = computed({
  get: () => contentStore.contentOpen,
  set: val => {
    if (!val) {
      contentStore.close();
    }
  },
});

// Side panel (content drawer, desktop): flag on <body> so map controls
// and the utility cluster can shift left and stay clear of the drawer.
// Only the DESKTOP drawer (≥ md, !isMobile — Quasar md starts at
// $breakpoint-sm + 1 = 770px here) takes layout space — the mobile
// bottom sheet overlays, so it must NOT set the flag. Watching isMobile
// too means crossing the breakpoint while open removes (or adds) the
// flag together with the drawer/sheet swap.
const desktopDrawerWidth = computed(() => ($q.screen.gt.md ? 460 : 380));
watch(
  [contentDrawerOpen, isMobile, desktopDrawerWidth],
  ([open, mobile, width]) => {
    const shift = open && !mobile;
    document.body.classList.toggle('wd-sidepanel-open', shift);
    // Panel slot width — ALWAYS set on desktop: the topbar pill reserves
    // this space in BOTH panel states (it rests at (viewport − panel)/2,
    // so opening/closing hut details moves nothing). The shift transforms
    // in _dark.scss additionally require .wd-sidepanel-open, so only the
    // open state actually displaces chrome. Mobile has no desktop panel.
    document.body.style.setProperty('--wd-panel-w', mobile ? '0px' : `${width}px`);
  },
  { immediate: true }
);

// Mobile bottom sheet ref (for programmatic snap control)
const bottomSheetRef = ref<InstanceType<typeof WdBottomSheet> | null>(null);

// Desktop drawer: shadow the header once the content is scrolled
const drawerContentScrolled = ref(false);
const headerScrolled = ref(false);

function onLayoutScroll(info: { position: number }): void {
  headerScrolled.value = (info.position ?? 0) > 2;
}

interface DrawerScrollInfo {
  verticalPosition?: number;
}

function onDrawerScroll(info: DrawerScrollInfo): void {
  drawerContentScrolled.value = (info.verticalPosition ?? 0) > 2;
}

// When new content is opened while the sheet is already showing (e.g. another
// hut is clicked on the map), keep the sheet at its current snap position and
// only reset the content scroll so the new content starts at the top. Fresh
// opens (sheet was entirely closed) naturally start at the initial snap point.
// On desktop the ref is null (sheet not rendered), making this a no-op.
watch(
  () => contentStore.contentSlug ?? contentStore.contentId,
  () => {
    if (contentStore.contentOpen) {
      bottomSheetRef.value?.onContentChanged();
    }
  }
);

// Static component map with markRaw (prevents re-evaluation)
const componentMap: Record<string, { title: Component; content: Component; actions: Component }> = {
  place: {
    title: markRaw(
      defineAsyncComponent(() => import('@/components/content/place/WdPlaceTitle.vue'))
    ),
    content: markRaw(
      defineAsyncComponent(() => import('@/components/content/place/WdPlaceContent.vue'))
    ),
    actions: markRaw(
      defineAsyncComponent(() => import('@/components/content/place/WdPlaceActions.vue'))
    ),
  },
};

// Computed selects from static map
const contentTitleComponent = computed(() => {
  const type = contentStore.contentType;
  if (!type || !componentMap[type]) return null;
  return componentMap[type].title ?? null;
});

const contentActionsComponent = computed(() => {
  const type = contentStore.contentType;
  if (!type || !componentMap[type]) return null;
  return componentMap[type].actions ?? null;
});

function closeContent() {
  contentStore.close();
}

const appTitle = getEnv('WODORE_APP_NAME') || 'Wodore';
const appEnv = getEnv('WODORE_ENV') || 'production';
const officialUrl = getEnv('WODORE_OFFICIAL_URL') || '';
const isStaging = computed(() => appEnv === 'staging' || appEnv === 'preview');
const isNotProduction = computed(() => appEnv !== 'production');
const metaData = {
  title: appTitle,
  meta: {
    description: {
      name: 'description',
      content: i18n.global.t('meta.description'),
    },
  },
};
watchEffect(() => {
  if (route.name == 'map') {
    useMeta(metaData);
  }
});
useMeta(() => {
  if (!isStaging.value) {
    return {};
  }
  return {
    meta: {
      robots: {
        name: 'robots',
        content: 'noindex,nofollow,noarchive',
      },
    },
  };
});

onMounted(() => {
  if (isNotProduction.value && officialUrl && !process.env.DEV) {
    $q.notify({
      type: 'warning',
      color: 'negative-800',
      textColor: 'white',
      message: `This is a ${appEnv} environment.`,
      html: true,
      caption: `<a href="${officialUrl}" target="_blank" rel="noopener" style="color: inherit; text-decoration: underline">Goto production version.</a>`,
      timeout: 10000,
      progress: true,
      position: 'bottom',
      actions: [{ icon: 'wd-close', color: 'white', dense: true, round: true }],
    });
  }
});
</script>
<style lang="scss">
.wd-surface {
  background: var(--wd-surface) !important;
}

.wd-ink-soft-text {
  color: var(--wd-ink-soft) !important;
}

.app-header {
  backdrop-filter: blur(10px);
  // Night (default here): pine bar, paper text. Day gets the lighter bar
  // via the body--light override below.
  color: $white;
  background-color: rgba(17, 33, 25, 0.88) !important;
}

// API progress bar pinned to the bottom edge of the header toolbar —
// absolutely positioned so it never shifts the layout when appearing
.header-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1;
}

// Day: the incumbent wodore.com sage-pine toolbar (dark-200, lighter than
// Night's pine) with cream text and white-pill buttons.
body.body--light .app-header {
  color: #f2f7f4;
  background-color: rgba(49, 94, 71, 0.92) !important;
}

// Header buttons: flat icon chrome in BOTH themes (user rule: no icon
// bg) — cream icons on the Day sage bar, ice icons on the Night pine bar.
// The date field keeps its light chip (it is a field, not an icon).
.app-header .q-btn {
  background: transparent !important;
  border-width: 0 !important;
  box-shadow: none !important;
}

.app-header .q-btn:hover {
  background: rgba(255, 255, 255, 0.16) !important;
}

body.body--light .app-header .q-btn .q-icon,
body.body--light .app-header .q-btn .text-icon,
body.body--light .app-header .q-btn.text-icon,
body.body--light .app-header button.text-icon {
  color: #f2f7f4 !important;
  background: transparent !important;
}

// Hover wash must outrank the flat-chrome rule above (its (0,4,1)
// specificity beat the plain .app-header .q-btn:hover and froze hover
// transparent in Day - the "invisible hover" from the design review)
body.body--light .app-header .q-btn.text-icon:hover,
body.body--light .app-header button.text-icon:hover {
  background: rgba(255, 255, 255, 0.16) !important;
}

// Quasar draws button fills on ::before - kill it in the header
.app-header .q-btn::before {
  background: transparent !important;
  box-shadow: none !important;
}

// Wordmark "wo": theme ink on surfaces; cream on the header bars (both
// themes use green bars where dark ink would vanish)
.wd-wordmark-wo {
  color: var(--wd-ink);
}

.app-header .wd-wordmark-wo,
.app-header .text-black {
  color: #f2f7f4 !important;
}

body.body--light .app-header .text-black {
  color: #f2f7f4 !important;
}

body.body--dark .app-header .q-btn .q-icon,
body.body--dark .app-header .q-btn.text-icon,
body.body--dark .app-header .text-icon {
  color: #a9f0d2 !important;
}

// Diagonal preview ribbon at the top-left corner. Intentionally overlaps
// the header edge and is partially clipped by the viewport - that is the
// classic "ribbon" look, NOT a bug (owner confirmed).
.preview-badge {
  position: fixed;
  top: 1px;
  left: -26px;
  z-index: 6000;
  font-size: 11px;
  line-height: 10px;
  letter-spacing: 0.04em;
  text-transform: none;
  padding: 2px 32px 2px 26px;
  transform: rotate(-20deg);
  background-image: repeating-linear-gradient(
    -45deg,
    color('accent', 900),
    color('accent', 900) 6px,
    color('accent', 800) 6px,
    color('accent', 800) 12px
  );
  color: white;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  pointer-events: none;
}

// Native app: ribbon sits a bit lower to clear the header edge
body.capacitor .preview-badge {
  top: 8px;
}

// Critical CSS for nested QLayout in container mode (inside drawer)
// Without this, the layout wrappers collapse to 0 height
.q-layout-container > div > div {
  min-height: 0;
  max-height: 100%;
  height: 100%;
}

.q-layout-container .q-layout {
  min-height: 100%;
  height: 100%;
}

// Prevent wide content (e.g. Swiper sliders) from pushing the
// content drawer wider than its configured :width prop.
//
// Quasar's QDrawer sets inline width but no max-width or overflow.
// Wide children with large intrinsic min-width can push the aside
// element wider. These rules enforce containment on the drawer itself
// and its content wrapper.
// The content drawer's user classes (content-drawer) land on Quasar's inner
// .q-drawer__content div (NOT the aside) - target that element.
.q-drawer__content.content-drawer {
  overflow: hidden !important;
  background: var(--wd-surface);
  color: var(--wd-ink);

  // Drawer header scrolled state (owner 2026-09-28): a separation line
  // plus a solid surface - content visibly slides UNDER the header. The
  // old drop shadow was both rule-violating (panel-on-panel) and hard
  // to see against the pine tones.
  .q-header {
    border-bottom: 1px solid transparent;
    transition:
      border-color 0.15s ease,
      background-color 0.15s ease;
  }

  .q-header.content-drawer-header-scrolled {
    background: var(--wd-surface-deep);
    border-bottom-color: rgba(var(--wd-ink-rgb), 0.16);
  }
}
</style>
<template>
  <WdAnalytics />
  <q-layout view="hHh LpR fFf" class="overflow-hidden" @scroll="onLayoutScroll">
    <div v-if="isStaging" class="preview-badge">preview</div>
    <WdApiVersionBanner />
    <!-- FLOATING TOPBAR: search | date (highlight) | avatar ──────────── -->
    <!-- --under-menu: while the menu drawer is open the pill must slide
         UNDER it (Quasar's desktop-mode drawer aside is z 1000, this fixed
         topbar 2000 — without the drop the pill paints over the drawer
         and swallows its taps). The pill always rests at
         (viewport − panel)/2, so its left edge sits inside the 300px
         drawer band at 770-1099px (left-aligned) and at 1100-1265px
         (centered); above that the drop is invisible. Mobile already
         renders its drawer on top (aside z 3000 there). -->
    <div class="wd-topbar" :class="{ 'wd-topbar--under-menu': menuDrawerOpen }">
      <div class="wd-topbar__pill">
        <!-- Search (icon-only, opens search) -->
        <div class="wd-topbar__search">
          <WdPlaceSearchMenu v-if="!isMobile" class="wd-topbar__search-menu" />
          <WdPlaceSearchDialog v-else class="wd-topbar__search-dialog" />
        </div>

        <!-- Date (the highlighted core element — main pill width) -->
        <div class="wd-topbar__date">
          <WdSelectDate />
        </div>

        <!-- User / menu button (right edge, inside the pill) -->
        <!--<button class="text-icon" :aria-label="$t('menu')" @click="menuDrawerOpen = !menuDrawerOpen">-->
        <div class="wd-topbar__menu">
          <q-btn flat round :aria-label="$t('menu')" @click="menuDrawerOpen = !menuDrawerOpen">
            <q-icon size="sm" class="text-icon" name="wd-menu" />
          </q-btn>
        </div>
        <!-- <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"> -->
        <!--   <circle cx="12" cy="8" r="4" /> -->
        <!--   <path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6" /> -->
        <!-- </svg> -->
        <!--</button>-->

        <!-- API request progress — 1px line on the pill's bottom edge,
             clipped by the stadium border (subtle translucent ink).
             Decorative: aria-hidden, no pointer events. Fades/rises in
             200ms, fades/sinks out 150ms; static under reduced motion. -->
        <transition name="wd-progress">
          <q-linear-progress
            v-if="progressVisible"
            indeterminate
            size="1px"
            aria-hidden="true"
            class="wd-topbar__progress"
          />
        </transition>
      </div>

      <!-- Desktop-only utilities: top-right chip cluster (8px radius) -->
      <div v-if="showTopbarUtils" class="wd-topbar__utils">
        <WdFeedbackButton size="sm" />
        <WdLanguageSwitcher size="sm" />
        <WdThemeSwitcher size="sm" />
      </div>
    </div>

    <!-- MAIN DIALOG -->
    <q-dialog
      v-model="showDialog"
      :maximized="isMobile"
      backdrop-filter="blur(3px) saturate(180%) grayscale(60%)"
      class="dialog-radius"
      @hide="onDialogHide"
      @escape-key="onDialogHide"
    >
      <router-view name="dialog" v-slot="{ Component, route }">
        <component :is="Component" :key="route.path" />
      </router-view>
    </q-dialog>

    <!-- MENU -->
    <q-drawer
      v-model="menuDrawerOpen"
      :side="isMobile ? 'right' : 'left'"
      :width="300"
      :breakpoint="610"
      class="wd-menu-drawer"
      style="max-width: 80vw; z-index: 3000"
    >
      <!-- TOOLBAR mobile + small desktop: spans every width where the
           pill hides under the open drawer (< 1100px) — the WdMenuButton
           close is then the only pointer affordance to dismiss it -->
      <q-toolbar v-if="showDrawerToolbar" class="bg-primary-600 shadow-6">
        <q-toolbar-title>
          <WodoreLogo
            text
            class="text-h5"
            :text-color-left="$q.dark.isActive ? 'white' : 'black'"
          />
        </q-toolbar-title>

        <WdLanguageSwitcher size="md" />
        <WdThemeSwitcher size="md" />
        <WdFeedbackButton size="md" />

        <!-- MENU BUTTON close. No `mobile` prop: that gates rendering on
             $q.screen.xs, which would hide the close at 770-1099px and
             strand the open drawer. The arrow points out of whichever
             side the drawer is docked to (right on mobile, left above). -->
        <WdMenuButton :side="isMobile ? 'right' : 'left'" v-model="menuDrawerOpen" />
      </q-toolbar>
      <router-view name="menu" />
    </q-drawer>

    <!-- PAGE -->
    <q-page-container>
      <router-view v-slot="{ Component }">
        <component :is="Component" />
      </router-view>
    </q-page-container>

    <!-- Content Drawer (Desktop) -->
    <q-drawer
      v-if="!isMobile"
      v-model="contentDrawerOpen"
      side="right"
      :width="$q.screen.gt.md ? 460 : 380"
      :breakpoint="0"
      class="shadow-2 content-drawer"
    >
      <q-layout
        view="lhh LpR lff"
        container
        class="no-background wd-surface overflow-hidden"
        style="height: 100%"
      >
        <!-- Close button (top-LEFT, gold chip - reference design; the
             top-right corner belongs to the 3-dot actions menu) -->
        <div class="absolute z-max" style="top: 10px; left: 10px; pointer-events: none">
          <q-btn
            round
            dense
            icon="wd-close"
            @click="closeContent"
            class="wd-drawer-close"
            size="md"
            style="pointer-events: auto"
          />
        </div>

        <!-- Sticky Header (Actions + Title) -->
        <q-header
          class="wd-drawer-header"
          :class="{ 'content-drawer-header-scrolled': drawerContentScrolled }"
        >
          <!-- Actions Toolbar (Desktop only) -->
          <component
            v-if="contentActionsComponent && $q.screen.gt.sm"
            :is="contentActionsComponent"
            :slug="contentStore.contentSlug"
          />
          <!-- Title -->
          <component
            v-if="contentTitleComponent"
            :is="contentTitleComponent"
            :slug="contentStore.contentSlug"
          />
        </q-header>

        <!-- Scrollable Content -->
        <q-page-container class="fit" style="height: 100%">
          <q-scroll-area
            visible
            @scroll="onDrawerScroll"
            :thumb-style="{
              width: '6px',
              backgroundColor: '#998019',
              opacity: '0.5',
              borderRadius: '8px 0 0 8px',
            }"
            class="fit"
          >
            <q-page
              class="q-px-md"
              :style="{ height: '100%', maxWidth: ($q.screen.gt.md ? 460 : 380) + 'px' }"
            >
              <router-view name="content" v-slot="{ Component, route: contentRoute }">
                <transition name="fade" mode="out-in">
                  <component :is="Component" :key="contentRoute.path" />
                </transition>
              </router-view>
            </q-page>
          </q-scroll-area>
        </q-page-container>

        <!-- Footer (Actions for smaller desktop screens) -->
        <q-footer v-if="contentActionsComponent && !$q.screen.gt.sm" class="footer-toolbar">
          <component :is="contentActionsComponent" :slug="contentStore.contentSlug" />
        </q-footer>
      </q-layout>
    </q-drawer>
  </q-layout>

  <!-- Mobile Bottom Sheet (OUTSIDE QLayout, only on mobile) -->
  <!-- under-menu: the sheet drops below the site-menu drawer while it is
       open (same pattern as the pill's wd-topbar--under-menu) — the drawer
       aside sits at z 3000 and would otherwise tie with the sheet, which
       comes later in the DOM and paints over it. -->
  <WdBottomSheet
    v-if="isMobile"
    ref="bottomSheetRef"
    v-model="contentDrawerOpen"
    :class="{ 'under-menu': menuDrawerOpen }"
    @close="closeContent"
  >
    <!-- Close button (top-right corner) -->
    <div class="absolute" style="top: 10px; right: 10px; z-index: 1000">
      <q-btn
        round
        dense
        flat
        icon="wd-close"
        @click="closeContent"
        class="wd-ink-soft-text"
        size="md"
      />
    </div>

    <!-- Header slot -->
    <template #header>
      <div class="sheet-header-row q-px-md q-pt-sm q-pb-xs" style="padding-right: 50px">
        <component
          v-if="contentTitleComponent"
          :is="contentTitleComponent"
          :slug="contentStore.contentSlug"
        />
      </div>
    </template>

    <!-- Content (native scroll) -->
    <div class="q-px-md">
      <router-view name="content" v-slot="{ Component, route: contentRoute }">
        <transition name="fade" mode="out-in">
          <component :is="Component" :key="contentRoute.path" />
        </transition>
      </router-view>
    </div>

    <!-- Footer slot -->
    <template #footer>
      <component
        v-if="contentActionsComponent"
        :is="contentActionsComponent"
        :slug="contentStore.contentSlug"
      />
    </template>
  </WdBottomSheet>
</template>
